import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷二·20","description":"易小帖 - 卷二·20","frontmatter":{"title":"卷二·20","description":"易小帖 - 卷二·20"},"headers":[],"relativePath":"classics/yixiaotie/060.md","filePath":"classics/yixiaotie/060.md"}'),o={name:"classics/yixiaotie/060.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷二·20",tabindex:"-1"},[r("卷二·20 "),e("a",{class:"header-anchor",href:"#卷二·20","aria-label":"Permalink to “卷二·20”"},"​")],-1),e("p",null,"商瞿魯人，春秋時善易者，其為孔子弟子，他無可考，惟《漢》、《史》有雲，魯商瞿子木受易於孔子，以授魯橋庇子庸，庸授江東馯臂子弓，弓授燕周醜子家，子家授東武孫虞子乖，子乖授齊田何子裝。漢興，田何以齊田徙杜陵，號杜田生。是孔子之易，五傳至何，為漢代傳易之宗，而其親受孔子者，實商瞿也。若《乾鑿度》稱：「孔子生不知易本，偶筮其命，得旅，請益於商瞿氏，曰：子有聖知而無位。孔子泣而曰：鳯鳥不來，河無圖至，天之命也。於是始作十翼。」是夫子素不知易，反受教商瞿氏，而後作易傳，謬矣。若後儒作偽《子夏傳》有雲：孔子之易傳之子夏，商即子夏名。瞿子木者，別是一人。則橋庇子庸，馯臂子弓輩，皆連類並稱一人耶，抑兩人耶？",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
